test("Pi's tool_search finds and loads a deferred web tool", async () => {
	const requests = await withNativeEnv({ toolExposure: "deferred" }, async () => {
		const { faux, requests, captureRequest, start } = nativeHarness();
		faux.setResponses([
			(context) => {
